%[text] 发现2:Transfer 过程是layer 2为模版的，L2编码了早期的记忆，晚期的动作目的，并在迁移过程中共用了L2，而L5参与了行为
%[text:tableOfContents]{"heading":"目录"}
%%
ALB=TransferLearning.AudioLightBaseline; %[output:3667bb33] %[output:56ec0417] %[output:2fe5f784] %[output:47ba6814] %[output:077db265] %[output:503c32e1] %[output:407749b8] %[output:0e91bfab] %[output:1cc0cc7d] %[output:7b822f3b] %[output:7793c51d] %[output:151d4456] %[output:0200df14] %[output:4496a8cc] %[output:141b559f] %[output:62b04991] %[output:367f89dd] %[output:6b28b838] %[output:64561ee5] %[output:9b83d326] %[output:03160473] %[output:1650821a] %[output:15d43a41] %[output:03c35046] %[output:490d560b] %[output:797a104c] %[output:9c894325] %[output:38ae7a2f] %[output:037de095] %[output:7b9d2528] %[output:0130b3e9] %[output:5ccff9e7] %[output:0722bf57]
QueryTablePath=TransferLearning.ProjectPath('查询表.xlsx');
%%
%[text] # 学习早期
%[text] 2层功能：记录刺激
%[text] 1. 时间提前
%[text] 2. 活动低
%[text] 3. 对cue不响应 \
%[text] L5无时间提前
%[text] L2早于L5
%[text] ## A
%[text] 群体活动总览：1s内达到基线3倍标准差的所有细胞
EnsembleA=UniExp.NtatsCellStrip(ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2A'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median));
[~,Index]=ismember(EnsembleA.CellUID,ALB.Cells.CellUID);
ZLayer=ALB.Cells.ZLayer(Index);
%%
EnsembleLogical=max(EnsembleA.NTATS.AudioWater(:,25:32),[],2)>std(EnsembleA.NTATS.AudioWater(:,1:24),[],2)*3;
Layer2Logical=ZLayer=="MOp2/3";
Layer5Logical=ZLayer=="MOp5";
Ensemble2=Layer2Logical&EnsembleLogical;
Ensemble5=Layer5Logical&EnsembleLogical;
%%
LayerTitles=["Layer2 "+MATLAB.SignificantFixedpoint(sum(Ensemble2)/sum(Layer2Logical)*100,2)+"%","Layer5 "+MATLAB.SignificantFixedpoint(sum(Ensemble5)/sum(Layer5Logical)*100,2)+"%"];
Phases=["AudioOnly","WaterOnly","AudioWater"];
HLData=table;
HLData.(LayerTitles(1))=permute(EnsembleA.NTATS{Ensemble2,:,Phases},[3,1,2]);
HLData.(LayerTitles(2))=permute(EnsembleA.NTATS{Ensemble5,:,Phases},[3,1,2]);
HLData.Properties.RowNames=Phases';
%%
XLine=timetable;
%timetable的局限性，必须先制定列后指定时间
XLine.LineStyle=":k";
XLine.Time=seconds(0);
Fig=figure;
[Layout,Axes,Lines,ColorBar]=UniExp.HeatmapLine(HLData(:,LayerTitles),seconds([-3,3]),XLine=XLine);
legend(Lines(:,1),["Layer 2","Layer 5"],Location=MATLAB.Graphics.OptimizedLegendLocation(Lines(:,1)));
ylabel(Axes(3,1),'z-score ± SEM');
ColorBar.Label.String='z-score';
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow);
title(Layout,'Ensemble Naive');
print(Fig,TransferLearning.ProjectPath('Fig2A.svg'),'-dsvg');
%%
%[text] ## B
Fig=figure; %[output:197138a2]
Layout=tiledlayout(2,2,TileSpacing='tight',Padding='compact');%Padding如果用tight，右边坐标轴会出界 %[output:197138a2]
%[text] 2层时间提前：AudioWater相比于AudioOnly
GroupNtats=UniExp.NtatsCellStrip(ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2B12'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:2c7f2352]
EnsembleB12=GroupNtats(max(GroupNtats.NTATS.AudioWater(:,25:32),[],2)>std(GroupNtats.NTATS.AudioWater(:,1:24),[],2)*3,:);
[~,Index]=ismember(EnsembleB12.CellUID,ALB.Cells.CellUID);
EnsembleB12.Mouse=ALB.Cells.Mouse(Index);
EnsembleB12.Signal=EnsembleB12.NTATS{:,25:end,["AudioOnly","AudioWater"]};
MouseSignal=groupsummary(EnsembleB12,'Mouse',@(Signal)mean(Signal,1),'Signal');
[~,RisingTime]=max(diff(MouseSignal.fun1_Signal,1,2),[],2);
nexttile; %[output:197138a2]
UniExp.BarScatterCompare(array2table(permute(RisingTime*milliseconds(125),[1,3,2]),'VariableNames',["🔊","🔊💧"]),false,table(["🔊","🔊💧"],'VariableNames',"GroupPair")); %[output:197138a2]
ylabel('Rising time (s)'); %[output:197138a2]
title('Layer 2'); %[output:197138a2]
YLim=ylim;
ylim([0,YLim(2)]); %[output:197138a2]
%[text] 2层活动强度：AudioWater比AudioOnly强
Response=max(MouseSignal.fun1_Signal(:,1:24,:),[],2);
nexttile; %[output:197138a2]
UniExp.BarScatterCompare(table(Response(:,:,1),Response(:,:,2),'VariableNames',["🔊","🔊💧"]),false,table(["🔊","🔊💧"],'VariableNames',"GroupPair")); %[output:197138a2]
ylabel('Max z-score in 1s'); %[output:197138a2]
title('Layer 2'); %[output:197138a2]
YLim=ylim;
ylim([0,YLim(2)]); %[output:197138a2]
%[text] 5层：AudioWater与WaterOnly时间比较
GroupNtats=UniExp.NtatsCellStrip(ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2B3'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:5faa1f16]
EnsembleB3=GroupNtats(max(GroupNtats.NTATS.AudioWater(:,25:32),[],2)>std(GroupNtats.NTATS.AudioWater(:,1:24),[],2)*3,:);
[~,Index]=ismember(EnsembleB3.CellUID,ALB.Cells.CellUID);
EnsembleB3.Mouse=ALB.Cells.Mouse(Index);
EnsembleB3.Signal=EnsembleB3.NTATS{:,25:end,["WaterOnly","AudioWater"]};
MouseSignal=groupsummary(EnsembleB3,'Mouse',@(Signal)mean(Signal,1),'Signal');
[~,RisingTime]=max(diff(MouseSignal.fun1_Signal,1,2),[],2);
nexttile; %[output:197138a2]
UniExp.BarScatterCompare(array2table(permute(RisingTime*milliseconds(125),[1,3,2]),'VariableNames',["💧","🔊💧"]),false,table(["💧","🔊💧"],'VariableNames',"GroupPair")); %[output:197138a2]
ylabel('Rising time (s)'); %[output:197138a2]
title('Layer 5'); %[output:197138a2]
YLim=ylim;
ylim([0,YLim(2)]); %[output:197138a2]
%[text] L2早于L5
EnsembleB4=ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2B4'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median); %[output:4fd3bba0]
RisingTime=struct;
for L=["Layer2","Layer5"]
	NTATS=EnsembleB4.(L);
	NTATS=NTATS(max(NTATS.NTATS(:,25:32),[],2)>std(NTATS.NTATS(:,1:24),[],2)*3,:);
	[~,Index]=ismember(NTATS.CellUID,ALB.Cells.CellUID);
	NTATS.Mouse=ALB.Cells.Mouse(Index);
	NTATS.Signal=NTATS.NTATS(:,25:end);
	MouseSignal=groupsummary(NTATS,'Mouse',@(Signal)mean(Signal,1),'Signal');
	[~,RT]=max(diff(MouseSignal.fun1_Signal,1,2),[],2);
	RisingTime.(L)=RT*milliseconds(125);
end
nexttile; %[output:197138a2]
UniExp.BarScatterCompare(RisingTime,false,table(["Layer2","Layer5"],'VariableNames',"GroupPair")); %[output:197138a2]
ylabel('Rising time (s)'); %[output:197138a2]
YLim=ylim;
ylim([0,YLim(2)]); %[output:197138a2]
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow); %[output:197138a2]
Layout.Padding="compact";
print(Fig,TransferLearning.ProjectPath('Fig2B.svg'),'-dsvg'); %[output:197138a2]
%%
%[text] # 学习后和迁移过程
%[text] L2功能：指导L5行动
%[text] 1. 时间提前
%[text] 2. 活动高
%[text] 3. 形成correlation ensemble？ \
%[text] L5
%[text] 1. 时间提前
%[text] 2. 响应增强 \
%[text] L2与L5 同时?
%[text] 2层：指导L5 transfer
%[text] 1. 时间提前
%[text] 2. 活动低 \
%[text] （反应时间有变化么？）
%[text] （分trial 后，反应概率下降：显示cue的变化）
%[text] 5层
%[text] 1. 时间提前
%[text] 2. 响应弱 \
%[text] 相同Ensemble？
%[text] L2与L5同时？
%[text] ## C
EnsembleCD=ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2CD'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median); %[output:24dbb546]
%%
EnsembleC=UniExp.NtatsCellStrip(EnsembleCD);
%%
[~,Index]=ismember(EnsembleC.CellUID,ALB.Cells.CellUID);
ZLayer=ALB.Cells.ZLayer(Index);
Layer5Logical=ZLayer=="MOp5";
Layer2Logical=~Layer5Logical;
EnsembleLogical=max(EnsembleC.NTATS.Learned(:,25:32),[],2)>std(EnsembleC.NTATS.Learned(:,1:24),[],2)*3;
Ensemble2=Layer2Logical&EnsembleLogical;
Ensemble5=Layer5Logical&EnsembleLogical;
LayerTitles=["Layer2 "+MATLAB.SignificantFixedpoint(sum(Ensemble2)/sum(Layer2Logical)*100,2)+"%","Layer5 "+MATLAB.SignificantFixedpoint(sum(Ensemble5)/sum(Layer5Logical)*100,2)+"%"];
Phases=["Naive","Learned","Transfer"];
XLine=timetable;
%timetable的局限性，必须先指定列后指定时间
XLine.LineStyle=[":k";"-k"];
XLine.Time=seconds([0;1]);
Fig=figure;
[Layout,Axes,Lines,ColorBar]=UniExp.HeatmapLine(table(permute(EnsembleC.NTATS{Ensemble2,:,Phases},[3,1,2]),permute(EnsembleC.NTATS{Ensemble5,:,Phases},[3,1,2]),'VariableNames',LayerTitles,'RowNames',Phases),seconds([-3,3]),XLine=XLine);
legend(Lines(:,1),["Layer 2","Layer 5"],Location=MATLAB.Graphics.OptimizedLegendLocation(Lines(:,1)));
ylabel(Axes(3,1),'z-score ± SEM');
ColorBar.Label.String='z-score';
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow);
title(Layout,'Ensemble Learned')
print(Fig,TransferLearning.ProjectPath('Fig2C.svg'),'-dsvg');
%%
%[text] ## D
%[text] 时间统计
Fig=figure; %[output:15838ef0]
Layout=tiledlayout(2,3,TileSpacing='tight',Padding='compact'); %[output:15838ef0]
EnsembleCD.Naive.Phase(:)="Naive";
EnsembleCD.Learned.Phase(:)="Learned";
EnsembleF=[EnsembleCD.Naive;EnsembleCD.Learned];
EnsembleF=EnsembleF(max(EnsembleF.NTATS(:,25:32),[],2)>std(EnsembleF.NTATS(:,1:24),[],2)*3,:);
[~,Index]=ismember(EnsembleF.CellUID,ALB.Cells.CellUID);
EnsembleF.ZLayer=ALB.Cells.ZLayer(Index);
EnsembleF.Mouse=ALB.Cells.Mouse(Index);
EnsembleF.Signal=EnsembleF.NTATS(:,25:end);
MouseSignal=groupsummary(EnsembleF,["Mouse","Phase","ZLayer"],@(Signal)mean(Signal,1),'Signal');
[~,RisingTime]=max(diff(MouseSignal.fun1_Signal,1,2),[],2);
MouseSignal.RisingTime=RisingTime*milliseconds(125);
TimeComparison=UniExp.TabularAnovaN(MouseSignal.RisingTime,MouseSignal(:,["Phase","ZLayer"]),Comparison=table(["Naive","Learned";"Naive","Learned";"Learned","Learned"],["MOp2/3","MOp2/3";"MOp5","MOp5";"MOp2/3","MOp5"],'VariableNames',["Phase","ZLayer"]),Model=2,Display=false);
BarData=groupsummary(MouseSignal,["Phase","ZLayer"],["mean","std"],"RisingTime");
BarData.SEM=BarData.std_RisingTime./sqrt(BarData.GroupCount);
nexttile; %[output:15838ef0]
Bars=bar(reshape(BarData.mean_RisingTime,2,2)); %[output:15838ef0]
hold on; %[output:15838ef0]
EBs=errorbar([Bars.XEndPoints],[Bars.YEndPoints],[],BarData.SEM,'k',LineWidth=2,LineStyle='none'); %[output:15838ef0]
Descriptors=array2table([1,3;2,4;1,2],VariableNames=["IndexA","IndexB"]);
Descriptors.ObjectA(:)=EBs;
Descriptors.Text="p="+MATLAB.SignificantFixedpoint(TimeComparison.PValue,2);
MATLAB.Graphics.PLine(Descriptors); %[output:15838ef0]
colororder([1,0,1;0,0.5,0]); %[output:15838ef0]
YLim=ylim;
ylim([0,YLim(2)]); %[output:15838ef0]
xticklabels(["Layer 2","Layer 5"]); %[output:15838ef0]
ylabel('Rising time'); %[output:15838ef0]
%[text] 峰值统计
MouseSignal.Response=max(MouseSignal.fun1_Signal(:,1:24),[],2);
ResponseComparison=UniExp.TabularAnovaN(MouseSignal.Response,MouseSignal(:,["Phase","ZLayer"]),Comparison=table(["Naive","Learned";"Naive","Learned"],["MOp2/3","MOp2/3";"MOp5","MOp5"],'VariableNames',["Phase","ZLayer"]),Model=2,Display=false);
BarData=groupsummary(MouseSignal,["Phase","ZLayer"],["mean","std"],"Response");
BarData.SEM=BarData.std_Response./sqrt(BarData.GroupCount);
nexttile; %[output:15838ef0]
Bars=bar(reshape(BarData.mean_Response,2,2)); %[output:15838ef0]
hold on; %[output:15838ef0]
EBs=errorbar([Bars.XEndPoints],[Bars.YEndPoints],[],BarData.SEM,'k',LineWidth=2,LineStyle='none'); %[output:15838ef0]
Descriptors=array2table([1,3;2,4],VariableNames=["IndexA","IndexB"]);
Descriptors.ObjectA(:)=EBs;
Descriptors.Text="p="+MATLAB.SignificantFixedpoint(ResponseComparison.PValue,2);
MATLAB.Graphics.PLine(Descriptors); %[output:15838ef0]
colororder([1,0,1;0,0.5,0]); %[output:15838ef0]
YLim=ylim;
ylim([0,YLim(2)]); %[output:15838ef0]
xticklabels(["Layer 2","Layer 5"]); %[output:15838ef0]
ylabel('Max z-score in 1s'); %[output:15838ef0]
L=legend(Bars,"Ensemble "+unique(BarData.Phase)); %[output:15838ef0]
L.Layout.Tile=3; %[output:15838ef0]
%[text] LT对比
EnsembleD2=UniExp.NtatsCellStrip(rmfield(EnsembleCD,'Naive'));
EnsembleD2=EnsembleD2(max(EnsembleD2.NTATS.Learned(:,25:32),[],2)>std(EnsembleD2.NTATS.Learned(:,1:24),[],2)*3,:);
[~,Index]=ismember(EnsembleD2.CellUID,ALB.Cells.CellUID);
EnsembleD2.ZLayer=ALB.Cells.ZLayer(Index);
EnsembleD2.Mouse=ALB.Cells.Mouse(Index);
EnsembleD2.Signal=EnsembleD2.NTATS{:,25:end,["Learned","Transfer"]};
MouseSignal=groupsummary(EnsembleD2,["Mouse","ZLayer"],@(Signal)mean(Signal,1),'Signal');
AnovaTable=table;
AnovaTable.NTATS=[MouseSignal.fun1_Signal(:,:,1);MouseSignal.fun1_Signal(:,:,2)];
NumMouseLayers=height(MouseSignal);
AnovaTable.Phase(1:NumMouseLayers)="Learned";
AnovaTable.Phase(NumMouseLayers+1:end)="Transfer";
AnovaTable.ZLayer=[MouseSignal.ZLayer;MouseSignal.ZLayer];
AnovaTable.Mouse=[MouseSignal.Mouse;MouseSignal.Mouse];
[~,RisingTime]=max(diff(AnovaTable.NTATS,1,2),[],2);
AnovaTable.RisingTime=RisingTime*milliseconds(125);
AnovaTable.Response=max(AnovaTable.NTATS(:,1:24),[],2);
TimeComparison=UniExp.TabularAnovaN(AnovaTable.RisingTime,AnovaTable(:,["Phase","ZLayer"]),Comparison=table(["Learned","Transfer";"Learned","Transfer";"Transfer","Transfer"],["MOp2/3","MOp2/3";"MOp5","MOp5";"MOp2/3","MOp5"],'VariableNames',["Phase","ZLayer"]),Model=2,Display=false);
BarData=groupsummary(AnovaTable,["Phase","ZLayer"],["mean","std"],"RisingTime");
BarData.SEM=BarData.std_RisingTime./sqrt(BarData.GroupCount);
nexttile(4); %[output:15838ef0]
Bars=bar(reshape(BarData.mean_RisingTime,2,2)); %[output:15838ef0]
hold on; %[output:15838ef0]
EBs=errorbar([Bars.XEndPoints],[Bars.YEndPoints],[],BarData.SEM,'k',LineWidth=2,LineStyle='none'); %[output:15838ef0]
Descriptors=array2table([1,3;2,4;1,2],VariableNames=["IndexA","IndexB"]);
Descriptors.ObjectA(:)=EBs;
Descriptors.Text="p="+MATLAB.SignificantFixedpoint(TimeComparison.PValue,2);
MATLAB.Graphics.PLine(Descriptors); %[output:15838ef0]
colororder([1,0,1;0,0.5,0]); %[output:15838ef0]
YLim=ylim;
ylim([0,YLim(2)]); %[output:15838ef0]
xticklabels(["Layer 2","Layer 5"]); %[output:15838ef0]
ylabel('Rising time'); %[output:15838ef0]
%[text] 峰值统计
ResponseComparison=UniExp.TabularAnovaN(AnovaTable.Response,AnovaTable(:,["Phase","ZLayer"]),Comparison=table(["Learned","Transfer";"Learned","Transfer"],["MOp2/3","MOp2/3";"MOp5","MOp5"],'VariableNames',["Phase","ZLayer"]),Model=2,Display=false);
BarData=groupsummary(AnovaTable,["Phase","ZLayer"],["mean","std"],"Response");
BarData.SEM=BarData.std_Response./sqrt(BarData.GroupCount);
nexttile; %[output:15838ef0]
Bars=bar(reshape(BarData.mean_Response,2,2)); %[output:15838ef0]
hold on; %[output:15838ef0]
EBs=errorbar([Bars.XEndPoints],[Bars.YEndPoints],[],BarData.SEM,'k',LineWidth=2,LineStyle='none'); %[output:15838ef0]
Descriptors=array2table([1,3;2,4],VariableNames=["IndexA","IndexB"]);
Descriptors.ObjectA(:)=EBs;
Descriptors.Text="p="+MATLAB.SignificantFixedpoint(ResponseComparison.PValue,2);
MATLAB.Graphics.PLine(Descriptors); %[output:15838ef0]
colororder([1,0,1;0,0.5,0]); %[output:15838ef0]
YLim=ylim;
ylim([0,YLim(2)]); %[output:15838ef0]
xticklabels(["Layer 2","Layer 5"]); %[output:15838ef0]
ylabel('Max z-score in 1s'); %[output:15838ef0]
L=legend(Bars,"Phase "+unique(BarData.Phase)); %[output:15838ef0]
L.Layout.Tile=6; %[output:15838ef0]
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow); %[output:15838ef0]
print(Fig,TransferLearning.ProjectPath('Fig2D.svg'),'-dsvg'); %[output:15838ef0]
