%[text] # 后期学习
%[text] 2层：分离新任务
%[text] 1. 时间提前
%[text] 2. 活动高 \
%[text] （形成 新correlation ensemble？）
%[text] 5层
%[text] 1. 时间提前
%[text] 2. 响应增强 \
%[text] 新Ensemble？
%[text] L2与L5同时？
%[text] ## E
EnsembleEF=ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2EF'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median); %[output:4645ea8c]
EnsembleE=UniExp.NtatsCellStrip(EnsembleEF);
[~,Index]=ismember(EnsembleE.CellUID,ALB.Cells.CellUID);
ZLayer=ALB.Cells.ZLayer(Index);
Layer5Logical=ZLayer=="MOp5";
Layer2Logical=~Layer5Logical;
EnsembleLogical=max(EnsembleE.NTATS.Final(:,25:32),[],2)>std(EnsembleE.NTATS.Final(:,1:24),[],2)*3;
Ensemble2=Layer2Logical&EnsembleLogical;
Ensemble5=Layer5Logical&EnsembleLogical;
LayerTitles=["Layer2 "+MATLAB.SignificantFixedpoint(sum(Ensemble2)/sum(Layer2Logical)*100,2)+"%","Layer5 "+MATLAB.SignificantFixedpoint(sum(Ensemble5)/sum(Layer5Logical)*100,2)+"%"];
Phases=["Learned","Transfer","Final"];
XLine=timetable;
%timetable的局限性，必须先制定列后指定时间
XLine.LineStyle=[":k";"-k"];
XLine.Time=seconds([0;1]);
Fig=figure; %[output:5e48b03c]
[Layout,Axes,Lines,ColorBar]=UniExp.HeatmapLine(table(permute(EnsembleE.NTATS{Ensemble2,:,Phases},[3,1,2]),permute(EnsembleE.NTATS{Ensemble5,:,Phases},[3,1,2]),'VariableNames',LayerTitles,'RowNames',Phases),seconds([-3,3]),XLine=XLine); %[output:5e48b03c]
legend(Lines(:,1),["Layer 2","Layer 5"],Location=MATLAB.Graphics.OptimizedLegendLocation(Lines(:,1))); %[output:5e48b03c]
ylabel(Axes(3,1),'z-score ± SEM'); %[output:5e48b03c]
